const distractors = [
  "Continue and hide the issue during finishing.",
  "Change the drawing or specification to match the work.",
  "Leave it for the next trade without recording it.",
];

function practicalTask(route, raw, index) {
  const common = routeCommon[route.common];
  const number = String(index + 1).padStart(3, "0");
  const prefix = route.enrolmentId.replace(/[^A-Z0-9]/gi, "");
  const correct = `Pause at a safe point, correct the cause of ${raw.faults[0]}, then repeat the specified checks before continuing.`;
  return {
    id: `${prefix}-P${number}`,
    title: raw.title,
    category: raw.category,
    brief: raw.brief,
    timing: { shortMinutes: raw.practiceMinutes, fullMinutes: common.fullMockMinutes },
    mapsTo: raw.mapsTo.map((code) => route.enrolmentId === "ST0095" && code === "S23" ? "S15" : code),
    resources: [...common.resources, ...raw.extras],
    safetyControls: common.safety,
    sequence: raw.sequence.map((instruction, stepIndex) => ({ id: `S${stepIndex + 1}`, title: instruction, instruction })),
    evidenceCheckpoints: raw.checkpoints.map((prompt, checkpointIndex) => ({
      id: `E${checkpointIndex + 1}`,
      title: ["Set-out", "Hidden work", "Finished work"][checkpointIndex],
      prompt,
      accept: "image/*,video/*",
    })),
    checks: raw.checks,
    decision: {
      prompt: `A checkpoint reveals that ${raw.faults[0]}. What is the strongest response?`,
      options: [correct, ...distractors],
      correctIndex: 0,
      feedback: raw.answers[2],
    },
    commonFaults: raw.faults,
    questions: [
      { prompt: `Why is “${raw.sequence[1]}” important on this task?`, guide: raw.answers[0] },
      { prompt: "How would you check that this work meets the drawing or specification?", guide: raw.answers[1] },
      { prompt: `What would you do if ${raw.faults[0]}?`, guide: raw.answers[2] },
    ],
    reviewAreas: [
      { id: "safety", label: "Safety and preparation", weight: 20 },
      { id: "method", label: "Method and sequence", weight: 20 },
      { id: "accuracy", label: "Measurements and checks", weight: 30 },
      { id: "finish", label: "Finished work", weight: 20 },
      { id: "questions", label: "Practical questions", weight: 10 },
    ],
  };
}

await mkdir(output, { recursive: true });
const index = { eviaPracticalIndex: 1, schemaVersion: 1, updated, totalBanks: routes.length, totalTasks: 0, banks: [] };
for (const route of routes) {
  if (route.tasks.length !== 12) throw new Error(`${route.enrolmentId} must contain exactly 12 practical tasks`);
  const tasks = route.tasks.map((task, taskIndex) => practicalTask(route, task, taskIndex));
  const bank = {
    eviaPracticalBank: 1,
    schemaVersion: 1,
    bankVersion: "1.0",
    updated,
    enrolmentId: route.enrolmentId,
    courseTitle: route.courseTitle,
    qualificationId: route.qualificationId,
    pathwayId: route.pathwayId,
    courseType: route.courseType,
    tasksPerSession: 1,
    taskCount: tasks.length,
    assessmentContext: route.context,
    sourceNote: "Original Evia practice tasks mapped to course criteria. These are not official awarding-body or end-point-assessment tasks and do not produce an official grade.",
    tasks,
  };
  const file = `${route.enrolmentId}-v1.json`;
  await writeFile(path.join(output, file), `${JSON.stringify(bank, null, 2)}\n`);
  index.totalTasks += tasks.length;
  index.banks.push({ enrolmentId: route.enrolmentId, path: file, taskCount: tasks.length });
}
await writeFile(path.join(output, "index-v1.json"), `${JSON.stringify(index, null, 2)}\n`);

const registryPath = path.join(root, "course-delivery", "registry-v1.json");
const registry = JSON.parse(await readFile(registryPath, "utf8"));
for (const entry of registry.courses) {
  const bank = index.banks.find((item) => item.enrolmentId === entry.enrolmentId);
  if (!bank) throw new Error(`Missing practical bank for ${entry.enrolmentId}`);
  entry.practicalBankPath = `practical-banks/${bank.path}`;
  entry.content.practical = "available-12-task-coach";
}
registry.updated = updated;
await writeFile(registryPath, `${JSON.stringify(registry, null, 2)}\n`);

console.log(`Built ${index.totalTasks} practical tasks across ${index.totalBanks} course banks.`);
